source("pre.R")
norm <- function(s) gsub("[ \n]+", " ", trimws(s))
sig <- function(d) { e <- html_elements(d, "body *"); nm <- html_name(e); keep <- nm %in% c("em","strong","a","code","pre","h1","h2","h3","h4","h5","h6","blockquote","ul","ol","li","img","hr","br","table","tr","th","td","del"); paste(nm[keep], collapse=" ") }
canon <- function(h) { h <- gsub("<(/?)b>", "<\\1strong>", h); h <- gsub("<(/?)i>", "<\\1em>", h); h }
mk <- function(h, show=TRUE, base=NULL) {
  d <- if (is.null(base)) html_parse(h) else html_parse(h, base_url=base); md <- html_markdown(d)
  back <- html_parse(commonmark::markdown_html(md, extensions = c("table","strikethrough")))
  t0 <- norm(html_text_clean(d)); t1 <- norm(html_text_clean(back))
  ok <- identical(t0, t1)
  if (show || !ok) cat(sprintf("%s %s\n   md: %s\n   back: %s\n", if (ok) "ok  " else "DIFF", encodeString(h), encodeString(md), encodeString(html_serialize(html_element(back,"body"), outer=FALSE))))
  invisible(ok)
}
